// Modo DIFÍCIL · Enseñanza bíblica (preguntas originales, revisadas).
// El juego baraja el orden de las respuestas al mostrarlas.
window.PREGUNTAS_DIFICIL = [{"section":"Evangelios · Jesús","q":"¿Qué significa que Jesús es “el camino, la verdad y la vida”?","refs":[["Juan 14:6-11","Jesús dijo que Él es el camino, la verdad y la vida, y que nadie llega al Padre sino por medio de Él. También explicó que conocerlo a Él es conocer al Padre, porque sus palabras y obras muestran al Padre."],["Hebreos 10:19-22","Por lo que Jesús hizo, podemos acercarnos a Dios con confianza, con un corazón sincero y lleno de fe."]],"a":["Jesús vino a mostrarnos el camino hacia Dios; si seguimos suficientemente bien sus enseñanzas, nuestra obediencia nos hace dignos de llegar al Padre.","Que Jesús es quien nos revela al Padre, nos da vida y por medio de Él podemos acercarnos a Dios.","Jesús es uno de los medios que Dios usa para acercarnos a Él; quienes siguen sinceramente otro camino también pueden llegar al Padre sin Cristo."],"correct":1,"ex":"Jesús no dijo solamente que conocía el camino. Él mismo es el camino. En Él conocemos verdaderamente al Padre y, por medio de su obra, tenemos acceso a Dios y recibimos vida."},
{"section":"Evangelios · Nueva vida","q":"¿Qué significa nacer de nuevo?","refs":[["Juan 3:3-8","Jesús enseñó que nadie puede ver el reino de Dios si no nace de nuevo. Este nacimiento viene del Espíritu."],["1 Pedro 1:23","Han nacido de nuevo, no de una semilla que muere, sino de una que permanece: la palabra viva de Dios."]],"a":["Nacer de nuevo ocurre cuando decidimos cambiar de vida; nuestra decisión y esfuerzo producen en nosotros esa nueva vida espiritual.","Nacer de nuevo significa que Dios perdona el pasado y después nosotros construimos, mediante obediencia, la nueva vida que necesitamos.","Recibir de Dios una vida nueva por la obra de su Espíritu, por medio de su Palabra."],"correct":2,"ex":"Nacer de nuevo es obra de Dios. No consiste simplemente en reformar la conducta o adoptar costumbres religiosas. Dios da nueva vida, y esa vida comienza a producir una transformación real."},
{"section":"Evangelios · Salvación","q":"¿Por qué vino Jesús al mundo?","refs":[["Lucas 19:10","El Hijo del Hombre vino a buscar y salvar lo que estaba perdido."],["Juan 3:16-17","Dios amó al mundo y dio a su Hijo para que quien cree en Él tenga vida eterna. Dios no envió a su Hijo para condenar al mundo, sino para que el mundo sea salvo por medio de Él."]],"a":["Para buscar y salvar a los perdidos y darnos vida por medio de Él.","Jesús vino principalmente a mostrarnos cómo vivir; quienes imitan suficientemente bien su ejemplo pueden reconciliarse con Dios por esa obediencia.","Jesús abrió una nueva oportunidad de salvación, pero cada persona debe completar su rescate mediante una vida suficientemente buena."],"correct":0,"ex":"Jesús vino como Salvador. Su enseñanza importa, pero su misión no se reduce a enseñarnos cómo comportarnos: vino a rescatar al perdido y reconciliarnos con Dios."},
{"section":"Evangelios · Fe","q":"Según Jesús, ¿qué es creer en Él?","refs":[["Juan 6:35-40","Jesús se presentó como el pan de vida. Quien viene a Él no tendrá hambre y quien cree en Él no tendrá sed. Él no rechazará al que viene a Él."],["Juan 3:16","Dios amó al mundo de tal manera que dio a su Hijo único, para que todo el que cree en Él no se pierda, sino que tenga vida eterna."]],"a":["Creer en Jesús consiste en aceptar como verdaderas sus enseñanzas; esa aceptación intelectual basta aunque nunca dependamos personalmente de Él.","Creer significa comprometerse a obedecer a Jesús hasta demostrar mediante nuestras obras que merecemos recibir la vida eterna.","Confiar en Jesús y acudir a Él para recibir la vida que Dios ofrece."],"correct":2,"ex":"La fe bíblica es más que reconocer un dato acerca de Jesús. Es confiar en Él, acudir a Él y descansar en la salvación que Dios ofrece por medio de su Hijo."},
{"section":"Evangelios · Arrepentimiento","q":"¿Qué significa arrepentirse?","refs":[["Marcos 1:14-15","Jesús anunció que el reino de Dios se había acercado y llamó a las personas a arrepentirse y creer en la buena noticia."],["Lucas 15:17-20","El hijo reconoció su condición, se levantó y regresó a su padre."]],"a":["Arrepentirse significa sentir suficiente dolor por el pecado; ese dolor es lo que consigue que Dios nos perdone.","Reconocer nuestro pecado, volvernos a Dios y responder con fe a su llamado.","Arrepentirse significa corregir nuestra conducta hasta compensar delante de Dios el mal que hicimos anteriormente."],"correct":1,"ex":"El arrepentimiento incluye reconocer que hemos ido en una dirección equivocada y volvernos a Dios. No es pagar nuestra deuda con buenas obras, sino responder a Dios con fe y un cambio real de dirección."},
{"section":"Evangelios · Discipulado","q":"¿Qué significa seguir a Jesús?","refs":[["Lucas 9:23-24","Jesús dijo que quien quiera seguirlo debe negarse a sí mismo, tomar su cruz cada día y seguirlo."],["Juan 12:26","Jesús dijo que quien quiera servirlo debe seguirlo, y donde Él esté, allí estará también su servidor."]],"a":["Reconocer a Jesús como Señor y aprender a vivir detrás de Él, aun cuando seguirlo tenga un costo.","Seguir a Jesús significa imitar suficientemente su conducta para llegar a ser dignos de pertenecerle.","Seguir a Jesús consiste en cumplir sus enseñanzas; mientras nuestra obediencia sea suficiente, no necesitamos depender de su gracia."],"correct":0,"ex":"Seguir a Jesús no es añadir una actividad religiosa a nuestra agenda. Es reconocer su autoridad, aprender de Él y orientar nuestra vida hacia Él."},
{"section":"Evangelios · Reino","q":"¿Qué es el reino de Dios en la enseñanza de Jesús?","refs":[["Marcos 1:14-15","Jesús anunció que el tiempo se había cumplido y que el reino de Dios se había acercado."],["Lucas 17:20-21","Jesús explicó que el reino de Dios no llega como un espectáculo que pueda señalarse simplemente con la vista; el reino estaba en medio de ellos."]],"a":["El reino de Dios es una sociedad que los seres humanos establecen cuando consiguen aplicar correctamente las leyes de Dios.","El gobierno y la autoridad de Dios que se hacen presentes y llaman a las personas a responderle.","El reino de Dios llega cuando una comunidad alcanza suficiente obediencia para establecer por sí misma el gobierno de Dios en la tierra."],"correct":1,"ex":"Cuando Jesús anuncia el reino, anuncia el gobierno de Dios acercándose a las personas. El Rey está actuando, salvando y llamándonos a vivir bajo su autoridad."},
{"section":"Evangelios · Gracia","q":"¿Qué enseña la parábola del fariseo y el cobrador de impuestos sobre acercarnos a Dios?","refs":[["Lucas 18:9-14","Un fariseo presentó sus méritos delante de Dios. El cobrador de impuestos pidió misericordia reconociendo su pecado. Jesús dijo que este último volvió a casa justificado."]],"a":["Dios justifica al pecador cuando su arrepentimiento produce suficientes buenas obras para demostrar que merece misericordia.","La misericordia de Dios completa la parte que falta después de que nuestras buenas obras aportan la mayor parte de la justicia necesaria.","Que Dios recibe al que reconoce su necesidad y busca su misericordia, no al que confía en su propia justicia."],"correct":2,"ex":"Jesús confronta la confianza en la propia justicia. No venimos ante Dios presumiendo nuestros méritos, sino reconociendo nuestra necesidad de misericordia."},
{"section":"Evangelios · Amor","q":"¿Qué quiso enseñar Jesús al decir que amemos a nuestros enemigos?","refs":[["Mateo 5:43-48","Jesús enseñó a amar a los enemigos y orar por quienes persiguen, recordando que el Padre muestra bondad incluso a quienes no lo honran."]],"a":["Que debemos buscar el bien incluso de quienes nos tratan mal, sin convertir el odio en nuestra respuesta.","Amar al enemigo significa no llamar pecado a lo que hace, porque señalar su maldad sería dejar de amarlo.","Amar al enemigo obliga a mantener cercanía y confianza con él aunque continúe haciéndonos daño; poner límites contradice el mandato de Jesús."],"correct":0,"ex":"Amar al enemigo no significa aprobar el mal ni permanecer indefenso ante el abuso. Significa que el mal recibido no gobierna nuestra respuesta: podemos buscar justicia sin alimentar odio ni venganza."},
{"section":"Evangelios · Oración","q":"¿Qué nos enseña Jesús sobre la oración?","refs":[["Mateo 6:5-13","Jesús enseñó a no orar para impresionar a otros ni a repetir palabras pensando que así seremos escuchados. Enseñó a dirigirnos al Padre y buscar su nombre, su reino, su voluntad y nuestra dependencia diaria."]],"a":["Dios concede lo que pedimos cuando alcanzamos suficiente fe; una petición no respondida demuestra normalmente que nuestra fe fue insuficiente.","La oración perseverante puede obligar a Dios a conceder algo que no quería dar si demostramos suficiente insistencia y fe.","Que la oración es una relación sincera con el Padre, no una actuación para impresionar a otros."],"correct":2,"ex":"Jesús presenta la oración como confianza y dependencia del Padre. No necesitamos actuar delante de Dios ni manipularlo con palabras."},
{"section":"Evangelios · Perdón","q":"¿Por qué el perdón ocupa un lugar tan importante en la vida cristiana?","refs":[["Mateo 18:21-35","Jesús contó acerca de un siervo al que le fue perdonada una deuda enorme, pero luego se negó a mostrar misericordia a otro. La parábola muestra la gravedad de recibir misericordia y negarnos a extenderla."]],"a":["Dios nos perdona porque nosotros primero perdonamos a los demás; nuestro perdón hacia ellos es la causa de que Él nos perdone.","Porque quien ha recibido misericordia de Dios es llamado a vivir mostrando misericordia a otros.","Perdonar significa que la ofensa deja de tener consecuencias y que ya no puede existir corrección, restitución ni límites."],"correct":1,"ex":"Perdonar no convierte el mal en bien ni elimina automáticamente sus consecuencias. Pero quien comprende la misericordia que ha recibido de Dios no puede tratar la venganza como su forma normal de vivir."},
{"section":"Evangelios · Cruz","q":"¿Por qué la muerte de Jesús es central en el Evangelio?","refs":[["Marcos 10:45","Jesús dijo que el Hijo del Hombre no vino para ser servido, sino para servir y dar su vida como rescate por muchos."],["Mateo 26:28","Jesús habló de su sangre derramada por muchos para el perdón de los pecados."]],"a":["Porque mediante su entrega Jesús hizo lo necesario para nuestro rescate y perdón.","La cruz fue principalmente el ejemplo de obediencia que debemos imitar; siguiendo ese ejemplo suficientemente bien podemos salvarnos.","La muerte de Jesús aporta una parte del perdón y nuestras buenas obras deben aportar la parte restante para que Dios nos acepte."],"correct":0,"ex":"La cruz no fue simplemente una tragedia ni solo un ejemplo de sacrificio. Jesús entregó voluntariamente su vida para rescatar y perdonar."},
{"section":"Evangelios · Resurrección","q":"¿Por qué importa que Jesús haya resucitado?","refs":[["Lucas 24:5-7","Los mensajeros anunciaron que Jesús no estaba entre los muertos, sino que había resucitado, tal como había dicho."],["1 Corintios 15:17-20","Pablo explica que si Cristo no resucitó, la fe sería inútil; pero Cristo verdaderamente resucitó de entre los muertos."]],"a":["La resurrección enseña que Dios dará vida eterna a quienes hayan acumulado suficiente obediencia, tal como recompensó la fidelidad de Jesús.","La importancia principal de la resurrección es confirmar que la enseñanza moral de Jesús era correcta; nuestra salvación no depende de que realmente resucitara.","Porque confirma la victoria de Cristo sobre la muerte y es esencial para nuestra esperanza."],"correct":2,"ex":"La resurrección pertenece al corazón del Evangelio. Cristo venció la muerte, y nuestra esperanza futura está unida a su victoria."},
{"section":"Evangelios · Identidad de Jesús","q":"¿Qué significa llamar a Jesús “Señor”?","refs":[["Lucas 6:46","Jesús preguntó por qué algunos lo llamaban Señor pero no hacían lo que Él decía."],["Filipenses 2:9-11","Dios exaltó a Jesús y llegará el día en que toda rodilla se doble y toda lengua reconozca que Jesucristo es Señor."]],"a":["Reconocer a Jesús como Señor significa obedecer suficientemente sus mandamientos para ganar el derecho de pertenecer a su reino.","Reconocer la autoridad de Jesús y responder a Él con fe y obediencia.","Jesús llega a ser nuestro Señor únicamente después de que nuestra conducta demuestra que somos dignos de someternos a Él."],"correct":1,"ex":"Llamar Señor a Jesús no es únicamente pronunciar un título. Es reconocer quién es Él y que su autoridad alcanza nuestra vida."},
{"section":"Evangelios · Grandeza","q":"Según Jesús, ¿qué significa ser grande?","refs":[["Marcos 10:42-45","Jesús contrastó el dominio de los gobernantes con sus discípulos: entre ellos, quien quiera ser grande debe servir. Él mismo vino para servir y dar su vida."]],"a":["Aprender a servir, siguiendo el ejemplo de Jesús.","La grandeza delante de Dios se gana acumulando actos de servicio; quien sirve más merece una posición superior en su reino.","Jesús enseñó que todo ejercicio de autoridad es contrario al servicio, por lo que un verdadero discípulo nunca debe dirigir ni tomar autoridad sobre otros."],"correct":0,"ex":"Jesús redefine la grandeza. En su reino, la grandeza no consiste en dominar a otros, sino en usar nuestra vida para servir."},
{"section":"Hechos · Espíritu Santo","q":"¿Para qué dio Dios el Espíritu Santo a sus discípulos?","refs":[["Hechos 1:8","Jesús prometió que sus discípulos recibirían poder cuando viniera sobre ellos el Espíritu Santo y serían sus testigos hasta los lugares más lejanos."],["Hechos 2:32-33","Pedro anunció que Jesús resucitado y exaltado recibió del Padre la promesa del Espíritu Santo y lo derramó sobre sus discípulos."]],"a":["El Espíritu Santo fue dado principalmente como una señal extraordinaria para identificar quiénes son espiritualmente superiores dentro de la iglesia.","El Espíritu nos da poder, pero conservar la salvación depende de usar correctamente ese poder y mantener suficiente obediencia.","Para capacitarlos para ser testigos de Cristo y vivir como su pueblo."],"correct":2,"ex":"El Espíritu no es dado como una insignia de superioridad espiritual. Dios capacita a su pueblo para dar testimonio de Cristo y vivir bajo su dirección."},
{"section":"Hechos · Evangelio","q":"¿Cuál fue el centro de la predicación de los primeros discípulos?","refs":[["Hechos 2:22-24","Pedro anunció a Jesús: entregado a la muerte, crucificado y resucitado por Dios."],["Hechos 4:12","Pedro declaró que la salvación se encuentra en Jesús y que no se ha dado otro nombre por el cual debamos ser salvos."]],"a":["Jesús, su muerte, su resurrección y la salvación que Dios ofrece por medio de Él.","Los apóstoles predicaban principalmente el ejemplo de Jesús: quien logra vivir de acuerdo con él puede reconciliarse con Dios.","Los apóstoles enseñaban que la muerte de Jesús inició la salvación, pero nuestras obras deben completar lo que falta."],"correct":0,"ex":"El centro del mensaje apostólico fue Cristo. Los apóstoles anunciaban quién es Jesús, lo que Dios hizo por medio de su muerte y resurrección, y llamaban a responder a Él."},
{"section":"Hechos · Iglesia","q":"¿Qué vemos en la primera comunidad cristiana acerca de la vida de la iglesia?","refs":[["Hechos 2:42-47","Los creyentes perseveraban en la enseñanza de los apóstoles, la comunión, el partimiento del pan y las oraciones. Compartían y cuidaban las necesidades entre ellos."]],"a":["Participar constantemente en la enseñanza, oración y comunión de la iglesia es lo que mantiene al creyente salvo; dejar de asistir hace que pierda esa salvación.","Los creyentes aprendían juntos, oraban, compartían la mesa y cuidaban unos de otros.","La iglesia posee y administra la salvación, de modo que una persona solo puede permanecer aceptada por Dios mientras permanezca formalmente dentro de ella."],"correct":1,"ex":"En Hechos, iglesia significa una comunidad reunida alrededor de Cristo. Aprenden la Palabra, oran, comparten y se cuidan mutuamente."},
{"section":"Hechos · Conversión","q":"Cuando las personas escuchaban el Evangelio, ¿a qué respuesta eran llamadas?","refs":[["Hechos 2:37-39","Al escuchar el mensaje, preguntaron qué debían hacer. Pedro los llamó al arrepentimiento y al bautismo en el nombre de Jesucristo."],["Hechos 16:30-31","Cuando el carcelero preguntó qué debía hacer para ser salvo, Pablo y Silas respondieron: cree en el Señor Jesús."]],"a":["El arrepentimiento, la fe y el bautismo aportan cada uno una parte de la salvación; Dios no puede perdonar hasta que completemos los tres requisitos.","Creer inicia la salvación, pero el bautismo y una vida obediente completan la justicia que Dios exige para aceptarnos.","A arrepentirse, creer en el Señor Jesús y expresar públicamente esa fe."],"correct":2,"ex":"El Evangelio pide una respuesta. Los apóstoles llamaban a arrepentirse y creer en Cristo. El bautismo acompañaba públicamente esa nueva identificación con Jesús."},
{"section":"Hechos · Misión","q":"¿Para quién es la buena noticia de Jesús?","refs":[["Hechos 1:8","Jesús envió a sus testigos desde Jerusalén hasta los lugares más lejanos de la tierra."],["Hechos 10:34-35","Pedro comprendió que Dios no muestra favoritismo por una nación, sino que recibe a personas de toda nación que lo buscan."]],"a":["Para todas las naciones; Dios llama a personas de todos los pueblos a Cristo.","Dios ofrece diferentes caminos de salvación según cada cultura; Jesús es solamente el camino que corresponde a quienes conocen el cristianismo.","El Evangelio es para todas las naciones, pero solo quienes demuestran suficiente obediencia llegan a merecer la salvación que ofrece."],"correct":0,"ex":"Hechos muestra cómo el Evangelio rompe fronteras. La salvación en Cristo no pertenece a una etnia, nación o clase social."},
{"section":"Romanos · Pecado","q":"¿Cuál es el problema fundamental del ser humano según Romanos?","refs":[["Romanos 3:22-24","No hay diferencia: todos pecaron y quedaron lejos de la gloria de Dios, y son justificados gratuitamente por su gracia mediante la redención que está en Cristo Jesús."]],"a":["El ser humano nace moralmente neutral; el problema aparece únicamente cuando acumula suficientes malas acciones para separarse de Dios.","Que todos hemos pecado y necesitamos la gracia de Dios.","Nuestro problema principal es ignorancia: si aprendemos correctamente la voluntad de Dios podemos restaurar por nosotros mismos nuestra relación con Él."],"correct":1,"ex":"Pablo coloca a todos en el mismo terreno: todos necesitamos gracia. Esto elimina tanto la desesperación del que piensa que no puede ser perdonado como el orgullo del que cree no necesitar perdón."},
{"section":"Romanos · Justificación","q":"¿Qué significa ser justificado por la fe?","refs":[["Romanos 5:1-2","Habiendo sido justificados por la fe, tenemos paz con Dios por medio de nuestro Señor Jesucristo y acceso a esta gracia."],["Romanos 3:28","Pablo concluye que una persona es justificada por la fe, aparte de las obras de la ley."]],"a":["Dios nos declara justos inicialmente por fe, pero después mantiene esa declaración solo mientras nuestra obediencia alcance un nivel suficiente.","Dios suma nuestra fe y nuestras obras; cuando juntas alcanzan la justicia necesaria, entonces nos justifica.","Que Dios nos declara en una relación correcta con Él por medio de la fe en Cristo, no porque hayamos ganado ese lugar."],"correct":2,"ex":"La justificación no significa que nunca volveremos a equivocarnos. Significa que nuestra aceptación delante de Dios descansa en Cristo y se recibe por fe, no como salario por nuestros méritos."},
{"section":"Romanos · Gracia","q":"Si somos salvos por gracia, ¿significa que podemos vivir deliberadamente en pecado sin que importe?","refs":[["Romanos 6:1-4","Pablo pregunta si debemos continuar en pecado para que aumente la gracia y responde con un no rotundo. Los que fueron unidos a Cristo fueron llamados a caminar en una vida nueva."]],"a":["No. La misma gracia que nos salva nos une a Cristo y nos llama a una vida nueva.","La gracia perdona nuestros pecados anteriores, pero desde ese momento debemos mantener la salvación mediante una obediencia suficiente.","Dios pone la gracia que comienza la salvación y nosotros ponemos las obras que la completan y aseguran."],"correct":0,"ex":"Pablo rechaza dos errores: pensar que podemos salvarnos por nuestras obras y pensar que la gracia vuelve irrelevante nuestra manera de vivir. La gracia nos salva y abre una vida nueva en Cristo."},
{"section":"Romanos · Espíritu","q":"¿Qué papel tiene el Espíritu Santo en la vida del creyente?","refs":[["Romanos 8:5-14","Pablo contrasta vivir dominados por la carne con vivir según el Espíritu. Los que son guiados por el Espíritu de Dios son hijos de Dios."],["Romanos 8:26","El Espíritu también ayuda en nuestra debilidad e intercede cuando no sabemos cómo orar."]],"a":["El Espíritu puede aconsejarnos y fortalecernos, pero la transformación del corazón depende finalmente de nuestra fuerza de voluntad.","Habita y obra en el creyente, guiándolo hacia una vida que agrada a Dios y ayudándolo en su debilidad.","Cuando el Espíritu habita en una persona elimina la posibilidad de volver a pecar; si peca otra vez demuestra que el Espíritu la abandonó."],"correct":1,"ex":"El Espíritu obra en la vida cotidiana del creyente. Nos guía, nos ayuda en nuestra debilidad y produce una nueva orientación hacia Dios."},
{"section":"Romanos · Seguridad","q":"¿Qué significa que nada puede separarnos del amor de Dios en Cristo?","refs":[["Romanos 8:35-39","Pablo enumera sufrimiento, persecución, peligro, muerte y muchas otras realidades, y afirma que ninguna criatura puede separarnos del amor de Dios que está en Cristo Jesús."]],"a":["Nada externo puede separarnos del amor de Dios, pero cada pecado hace que Dios deje de amarnos hasta que volvamos a obedecer.","La promesa significa que Dios impedirá que sus hijos sufran persecución, pérdida o circunstancias verdaderamente dolorosas.","Que aun en sufrimientos reales, ninguna fuerza creada puede arrancar al creyente del amor de Dios en Cristo."],"correct":2,"ex":"La promesa no es ausencia de sufrimiento. Pablo menciona precisamente circunstancias dolorosas y afirma que ninguna de ellas puede separar al pueblo de Dios de su amor en Cristo."},
{"section":"1 Corintios · Cruz","q":"¿Por qué Pablo pone la cruz de Cristo por encima de la sabiduría humana?","refs":[["1 Corintios 1:18-25","El mensaje de la cruz parece necedad para algunos, pero para los que son salvados es poder de Dios. La sabiduría de Dios supera la sabiduría humana."]],"a":["Porque la salvación de Dios no depende del orgullo intelectual humano, sino de lo que Dios hizo en Cristo.","La cruz demuestra que usar la razón es contrario a la fe; cuanto menos examinemos una enseñanza religiosa, más confiamos en Dios.","Dios escogió la cruz porque estudiar profundamente las cosas de Dios normalmente aleja de la fe y debe evitarse."],"correct":0,"ex":"Pablo no ataca el pensamiento. Ataca la pretensión de colocar la sabiduría humana por encima de Dios. La salvación no es un logro intelectual nuestro, sino obra de Dios en Cristo."},
{"section":"1 Corintios · Amor","q":"¿Cómo describe Pablo el amor cristiano?","refs":[["1 Corintios 13:4-7","El amor es paciente y bondadoso; no es envidioso ni orgulloso, no busca solamente lo suyo, no disfruta de la injusticia y se alegra con la verdad."]],"a":["Amar significa aprobar las decisiones del otro aunque sean pecaminosas; llamar pecado a algo que hace es incompatible con el amor.","El amor exige poner siempre los deseos de otra persona por encima del bien y la verdad, aunque esos deseos terminen dañándola.","Como una forma de vivir que busca el bien, se alegra con la verdad y no gira alrededor de uno mismo."],"correct":2,"ex":"El amor bíblico tiene sentimientos, pero no se reduce a ellos. Se expresa en paciencia, bondad, verdad y una disposición a buscar el bien del otro."},
{"section":"1 Corintios · Dones","q":"¿Para qué da Dios dones a los creyentes?","refs":[["1 Corintios 12:4-7","Hay diferentes dones, servicios y maneras de obrar, pero el mismo Dios obra en todos. A cada uno se le da una manifestación del Espíritu para el bien común."],["1 Corintios 12:25-27","Dios quiere que los miembros se cuiden mutuamente; juntos forman el cuerpo de Cristo."]],"a":["Los dones espirituales indican el rango de cada creyente; quien recibe un don más visible tiene mayor importancia delante de Dios.","Para servir al bien común y edificar al cuerpo de Cristo.","Los dones son premios por obediencia: cuanto más fiel es una persona, más importantes son los dones que Dios está obligado a darle."],"correct":1,"ex":"Los dones no son trofeos espirituales. Dios los da para servir. La diversidad de capacidades debe producir cuidado mutuo, no competencia."},
{"section":"1 Corintios · Resurrección","q":"¿Qué esperanza tiene el creyente frente a la muerte?","refs":[["1 Corintios 15:20-23","Cristo resucitó de los muertos como las primicias; los que pertenecen a Cristo también serán levantados."],["1 Corintios 15:52-57","Los muertos serán resucitados incorruptibles y la muerte finalmente será vencida."]],"a":["Que Dios resucitará a los que pertenecen a Cristo y la muerte no tendrá la última palabra.","La esperanza cristiana es abandonar definitivamente el cuerpo para vivir para siempre como espíritus; Dios no tiene propósito futuro para nuestros cuerpos.","Solo los creyentes que alcanzan suficiente santidad serán resucitados; los demás salvos permanecerán para siempre sin cuerpo."],"correct":0,"ex":"La esperanza cristiana no consiste simplemente en escapar del cuerpo. La resurrección de Jesús apunta a nuestra propia resurrección: Dios vencerá finalmente a la muerte."},
{"section":"2 Corintios · Nueva creación","q":"¿Qué significa ser una nueva creación en Cristo?","refs":[["2 Corintios 5:17-19","Si alguien está en Cristo, hay una nueva creación. Dios estaba reconciliando al mundo consigo mismo por medio de Cristo y nos dio el mensaje de la reconciliación."]],"a":["Ser nueva creación significa que desaparecen inmediatamente los viejos hábitos y luchas; si continúan, la persona todavía no ha nacido realmente de Dios.","Que en unión con Cristo comienza una realidad nueva: Dios nos reconcilia consigo y transforma nuestra vida.","Dios borra el pasado y nos permite empezar de cero, pero después nosotros debemos construir la justicia necesaria para seguir siendo aceptados."],"correct":1,"ex":"Nueva creación no significa perfección instantánea. Significa que nuestra relación con Dios y la dirección de nuestra vida han sido profundamente renovadas en Cristo."},
{"section":"Gálatas · Evangelio","q":"¿Por qué Pablo se opuso a añadir requisitos humanos al Evangelio?","refs":[["Gálatas 2:15-16","Pablo enseña que una persona no es justificada por las obras de la ley, sino por la fe en Jesucristo."],["Gálatas 5:1","Cristo nos hizo libres; Pablo llama a permanecer firmes y no volver a un yugo de esclavitud."]],"a":["La fe nos justifica al comienzo, pero después las reglas religiosas son necesarias para conservar la justificación que Cristo inició.","Cristo hizo casi todo lo necesario para salvarnos; nuestra obediencia a las reglas correctas completa la parte que su obra no cubrió.","Porque nuestra aceptación delante de Dios descansa en Cristo y no puede convertirse en un premio ganado mediante requisitos religiosos."],"correct":2,"ex":"Pablo protege el corazón del Evangelio: Cristo es suficiente para nuestra justificación. La obediencia cristiana nace de la fe y del Espíritu, no de intentar comprar la aceptación de Dios."},
{"section":"Gálatas · Fruto","q":"¿Qué es el fruto del Espíritu?","refs":[["Gálatas 5:22-25","El fruto del Espíritu es amor, alegría, paz, paciencia, amabilidad, bondad, fidelidad, humildad y dominio propio. Los que pertenecen a Cristo han crucificado la carne y son llamados a caminar por el Espíritu."]],"a":["El carácter que el Espíritu produce en quienes pertenecen a Cristo y aprenden a caminar bajo su dirección.","El fruto del Espíritu es la conducta que debemos producir para convencer a Dios de que merecemos conservar su Espíritu.","El Espíritu inicia el cambio, pero después el fruto depende exclusivamente de nuestra disciplina; si fallamos, deja de habitar en nosotros."],"correct":0,"ex":"Pablo habla de fruto, no de una actuación para ganar el favor de Dios. El Espíritu transforma progresivamente el carácter de quienes pertenecen a Cristo."},
{"section":"Efesios · Salvación","q":"¿Somos salvos por hacer buenas obras?","refs":[["Efesios 2:8-10","Han sido salvados por gracia mediante la fe. Esto no procede de ustedes: es regalo de Dios, no resultado de obras. Al mismo tiempo, fuimos creados en Cristo Jesús para buenas obras."]],"a":["La gracia cubre solamente la parte de justicia que nuestras obras no alcanzan; entre ambas completan lo necesario para salvarnos.","No. Somos salvados por gracia mediante la fe; las buenas obras son fruto de esa nueva vida, no su precio.","Somos salvos por gracia al comienzo, pero después las buenas obras mantienen activa esa salvación delante de Dios."],"correct":1,"ex":"Efesios mantiene juntas dos verdades: las obras no compran la salvación, pero la salvación produce una vida preparada para hacer el bien."},
{"section":"Efesios · Iglesia","q":"¿Qué significa que los creyentes forman un solo cuerpo en Cristo?","refs":[["Efesios 2:13-18","Cristo derribó la barrera de hostilidad y creó un solo pueblo, reconciliando a ambos con Dios por medio de la cruz."],["Efesios 4:1-6","Pablo llama a conservar la unidad del Espíritu: un cuerpo, un Espíritu, un Señor, una fe y un Dios y Padre."]],"a":["Ser un solo cuerpo significa que todos los creyentes verdaderos deben tener exactamente las mismas opiniones; cualquier desacuerdo demuestra que no hay unidad.","La iglesia solo puede ser un cuerpo si todos los creyentes pertenecen a una única organización humana bajo una sola autoridad terrenal.","Que Cristo reconcilia con Dios y reúne en un mismo pueblo a personas que antes estaban separadas."],"correct":2,"ex":"La unidad cristiana no borra todas las diferencias. Su fundamento es Cristo: personas distintas son reconciliadas con Dios y llamadas a vivir como un solo pueblo."},
{"section":"Efesios · Madurez","q":"¿Para qué sirven los ministerios y la enseñanza dentro de la iglesia?","refs":[["Efesios 4:11-16","Cristo dio diferentes servidores para preparar a los santos para la obra del ministerio y edificar el cuerpo hasta alcanzar madurez, creciendo en verdad y amor."]],"a":["Para equipar a los creyentes, edificar la iglesia y ayudarla a crecer hacia la madurez en Cristo.","Los ministerios existen para que unos pocos líderes hagan la obra espiritual mientras los demás creyentes se limitan a recibirla.","Los líderes reciben autoridad para controlar la vida espiritual de los miembros, porque la obediencia al líder es necesaria para conservar la salvación."],"correct":0,"ex":"El liderazgo bíblico no existe para producir espectadores. Su tarea incluye equipar al pueblo de Dios para servir y crecer juntos hacia la madurez."},
{"section":"Filipenses · Humildad","q":"¿Cómo presenta Pablo la humildad de Cristo?","refs":[["Filipenses 2:3-8","Pablo llama a no actuar por egoísmo y a considerar a otros. Presenta a Cristo, quien se humilló, tomó condición de siervo y fue obediente hasta la muerte de cruz."]],"a":["Humildad significa considerarnos sin valor y pensar que cualquier otra persona es necesariamente mejor que nosotros.","La humildad de Cristo exige permitir siempre que otros decidan por nosotros; defender un límite o necesidad propia es egoísmo.","Como renunciar al egoísmo y usar nuestra posición para servir, siguiendo el ejemplo de Cristo."],"correct":2,"ex":"La humildad bíblica no consiste en despreciarnos. Cristo muestra una humildad activa: no aferrarse al privilegio, sino entregarse para servir."},
{"section":"Filipenses · Contentamiento","q":"¿Qué quiso decir Pablo cuando afirmó que podía enfrentar toda situación en Cristo que lo fortalecía?","refs":[["Filipenses 4:11-13","Pablo explicó que había aprendido a estar contento tanto con abundancia como con necesidad. Podía enfrentar todas esas circunstancias por medio de Cristo que lo fortalecía."]],"a":["Cristo promete darnos capacidad para conseguir cualquier meta buena que deseemos, siempre que tengamos suficiente fe.","Que Cristo fortalecía a Pablo para permanecer fiel tanto en abundancia como en necesidad.","Filipenses 4:13 promete que un creyente fiel terminará superando toda escasez material y alcanzando prosperidad."],"correct":1,"ex":"El contexto habla de contentamiento. Pablo no promete éxito ilimitado; afirma que Cristo le da fortaleza para atravesar circunstancias muy diferentes sin abandonar su confianza."},
{"section":"Colosenses · Cristo","q":"¿Qué lugar ocupa Cristo en la vida cristiana?","refs":[["Colosenses 1:15-20","Cristo es presentado como supremo sobre la creación y cabeza de la iglesia. Por medio de Él Dios reconcilia todas las cosas consigo."],["Colosenses 2:6-7","Así como recibieron a Cristo Jesús como Señor, continúen viviendo en Él, arraigados y edificados en Él."]],"a":["Es el centro: recibimos a Cristo como Señor y continuamos creciendo arraigados en Él.","Cristo solamente abre la puerta de la salvación; después debemos avanzar más allá de Él mediante conocimientos y prácticas espirituales superiores.","Cristo es nuestro modelo, y la salvación depende finalmente de qué tan exactamente consigamos imitar su vida."],"correct":0,"ex":"El Nuevo Testamento no presenta a Cristo como una introducción que luego dejamos atrás. Él permanece en el centro de nuestra fe, crecimiento, reconciliación y esperanza."},
{"section":"1 Tesalonicenses · Esperanza","q":"¿Cómo debe afectar la esperanza del regreso de Cristo nuestra vida presente?","refs":[["1 Tesalonicenses 4:13-18","Pablo enseña que los creyentes no enfrentan la muerte sin esperanza, porque Jesús murió y resucitó y Dios reunirá con Él a los que le pertenecen."],["1 Tesalonicenses 5:6-11","A la luz del día del Señor, Pablo llama a estar despiertos, vivir con fe, amor y esperanza, y animarnos mutuamente."]],"a":["Prepararnos para el regreso de Cristo significa identificar correctamente las señales y calcular cuándo ocurrirá para no ser sorprendidos.","Cristo recibirá cuando vuelva a quienes hayan alcanzado una conducta suficientemente limpia para merecer entrar con Él.","Debe producir esperanza, vigilancia, fidelidad y ánimo mutuo."],"correct":2,"ex":"La esperanza futura no invita a especular obsesivamente con fechas. Pablo la conecta con sobriedad, fidelidad, consuelo y cuidado entre creyentes."},
{"section":"Cartas pastorales · Escritura","q":"¿Para qué es útil la Escritura?","refs":[["2 Timoteo 3:14-17","Las Sagradas Escrituras pueden hacer sabio para la salvación por la fe en Cristo. Toda Escritura es inspirada por Dios y útil para enseñar, corregir y formar en justicia, preparando al siervo de Dios para toda buena obra."]],"a":["La Escritura contiene las reglas que debemos cumplir para producir nuestra salvación y hacernos dignos de Cristo.","Para llevarnos a la sabiduría de la salvación en Cristo, enseñarnos, corregirnos y prepararnos para vivir y servir.","La Escritura transforma automáticamente a quien la lee, aunque esa persona rechace a Cristo y no crea su mensaje."],"correct":1,"ex":"La Escritura no fue dada como decoración religiosa ni como depósito de frases aisladas. Dios la usa para llevarnos a Cristo, enseñarnos y formar nuestra vida."},
{"section":"Cartas pastorales · Dinero","q":"¿Qué enseña el Nuevo Testamento acerca del amor al dinero?","refs":[["1 Timoteo 6:6-10","La piedad acompañada de contentamiento es una gran ganancia. El deseo de enriquecerse puede convertirse en una trampa, y el amor al dinero es raíz de muchos males."]],"a":["Que el amor al dinero puede esclavizar el corazón; somos llamados al contentamiento y a poner nuestra esperanza en Dios.","La prosperidad económica es una señal normal de la aprobación de Dios; un creyente fiel debería esperar hacerse materialmente próspero.","El dinero mismo es pecaminoso; por eso poseer más de lo estrictamente necesario es incompatible con una vida piadosa."],"correct":0,"ex":"Pablo no dice que el dinero en sí sea la raíz de todo mal. Advierte acerca del amor al dinero y del deseo que termina gobernando a la persona."},
{"section":"Hebreos · Sacerdocio de Cristo","q":"¿Por qué podemos acercarnos a Dios con confianza?","refs":[["Hebreos 4:14-16","Tenemos un gran sumo sacerdote, Jesús, que puede compadecerse de nuestras debilidades. Por eso somos invitados a acercarnos al trono de la gracia para recibir misericordia y ayuda."],["Hebreos 10:19-22","Por la obra de Jesús tenemos libertad para entrar y acercarnos a Dios con un corazón sincero y plena confianza de fe."]],"a":["Jesús abrió el acceso a Dios, pero solo podemos seguir acercándonos mientras nuestra conducta permanezca suficientemente limpia.","Porque Jesús es nuestro gran sumo sacerdote y por su obra tenemos acceso al trono de la gracia.","El sacrificio de Jesús y nuestra obediencia aportan cada uno una parte de la justicia necesaria para poder entrar ante Dios."],"correct":1,"ex":"Nuestra confianza no nace de creer que somos impecables. Precisamente porque necesitamos misericordia, nos acercamos confiando en Jesús y en lo que Él hizo."},
{"section":"Hebreos · Fe","q":"¿Qué es la fe según el ejemplo de Hebreos 11?","refs":[["Hebreos 11:1-6","La fe confía en lo que Dios ha prometido aunque todavía no se vea. Quien se acerca a Dios cree que Él existe y que responde a quienes lo buscan."],["Hebreos 11:8-10","Abraham obedeció el llamado de Dios sin conocer de antemano todo el camino, esperando lo que Dios había prometido."]],"a":["Fe es convencernos intensamente de que ocurrirá lo que deseamos; una convicción suficientemente fuerte hace que aquello suceda.","Las promesas de Dios se reciben cuando nuestra obediencia alcanza el nivel necesario; si no se cumplen es porque nuestra fe todavía fue insuficiente.","Confiar en Dios y sus promesas de tal manera que esa confianza dirige nuestros pasos."],"correct":2,"ex":"La fe bíblica tiene un objeto: Dios y su palabra. No es poder mental para hacer realidad nuestros deseos; es confianza en Dios que se expresa en obediencia."},
{"section":"Hebreos · Perseverancia","q":"¿Cómo debemos correr la carrera de la fe?","refs":[["Hebreos 12:1-3","Se nos llama a dejar el peso y el pecado que nos estorban, correr con perseverancia y mantener la mirada en Jesús, quien soportó la cruz."]],"a":["Mirando a Jesús, dejando lo que nos estorba y perseverando.","Perseverar significa mantener suficiente obediencia para impedir que Dios retire la salvación que inicialmente nos concedió.","La perseverancia depende finalmente de nuestra disciplina; Jesús puede ayudarnos, pero somos nosotros quienes garantizamos llegar al final."],"correct":0,"ex":"La perseverancia cristiana no se alimenta de competencia con otros. Hebreos dirige nuestros ojos hacia Jesús y nos llama a quitar aquello que impide avanzar."},
{"section":"Santiago · Fe y obras","q":"¿Qué quiere decir Santiago cuando afirma que la fe sin obras está muerta?","refs":[["Santiago 2:14-18","Santiago pregunta qué valor tiene afirmar que tenemos fe si esa fe nunca produce acción. Usa el ejemplo de ver a un hermano con necesidad y ofrecer solamente palabras."],["Santiago 2:26","Así como el cuerpo sin espíritu está muerto, la fe sin obras está muerta."]],"a":["Santiago enseña que la fe aporta una parte de nuestra justificación y las obras aportan la parte restante.","Las obras convierten una fe que todavía no salva en una fe salvadora; Dios nos justifica cuando ambas alcanzan juntas lo necesario.","Que una fe verdadera no permanece solamente en palabras, sino que produce fruto visible en la vida."],"correct":2,"ex":"Santiago no presenta las obras como precio de la salvación. Confronta una profesión de fe vacía: cuando la fe es real, comienza a hacerse visible en la manera de vivir."},
{"section":"Santiago · Pruebas","q":"¿Cómo puede un creyente enfrentar las pruebas?","refs":[["Santiago 1:2-5","Santiago enseña que las pruebas pueden producir perseverancia. Si alguien necesita sabiduría, debe pedirla a Dios, quien da generosamente."],["Santiago 1:12","Es dichoso quien persevera bajo la prueba, porque después de ser aprobado recibirá la corona de vida prometida a quienes aman a Dios."]],"a":["Toda prueba viene directamente de Dios y debemos permanecer en ella; intentar salir de una situación dañina significa resistir su voluntad.","Buscando sabiduría en Dios y permitiendo que la prueba produzca perseverancia.","Si una prueba continúa después de orar, normalmente significa que todavía no tenemos suficiente fe para que Dios la quite."],"correct":1,"ex":"La Biblia no exige fingir que el dolor es agradable. Santiago enseña que Dios puede usar las pruebas para formar perseverancia y nos invita a pedir sabiduría."},
{"section":"1 Pedro · Nuevo nacimiento","q":"¿Qué esperanza produce el nuevo nacimiento?","refs":[["1 Pedro 1:3-5","Dios, por su gran misericordia, nos hizo nacer de nuevo para una esperanza viva mediante la resurrección de Jesucristo, y para una herencia que no se destruye."]],"a":["Una esperanza viva basada en la resurrección de Jesús y en la herencia que Dios guarda para su pueblo.","El nuevo nacimiento solo nos da la posibilidad de recibir una herencia; conservarla depende finalmente de acumular suficiente fidelidad.","Una esperanza viva significa que Dios necesariamente mejorará nuestras circunstancias presentes como evidencia de que realmente somos sus hijos."],"correct":0,"ex":"Pedro escribe a creyentes que enfrentaban dificultades. Su esperanza no dependía de una vida cómoda, sino de la resurrección de Cristo y de lo que Dios había preparado."},
{"section":"1 Pedro · Santidad","q":"¿Qué significa vivir en santidad?","refs":[["1 Pedro 1:13-16","Pedro llama a poner completamente la esperanza en la gracia y a no vivir según los antiguos deseos. Como Dios es santo, su pueblo también es llamado a ser santo en toda su conducta."]],"a":["Ser santo significa evitar el contacto con personas no cristianas tanto como sea posible, porque relacionarnos con ellas nos hace impuros delante de Dios.","La santidad consiste en cumplir reglas externas que nos distinguen; mientras mantengamos esas reglas, el estado del corazón es secundario.","Pertenecer a Dios y permitir que esa nueva identidad transforme nuestra manera de vivir."],"correct":2,"ex":"La santidad no es superioridad religiosa. Dios llama a quienes le pertenecen a reflejar su carácter en su conducta."},
{"section":"1 Pedro · Sufrimiento","q":"¿Qué debe hacer un cristiano cuando sufre por hacer lo correcto?","refs":[["1 Pedro 2:19-23","Pedro señala a Cristo, quien sufrió injustamente sin responder con amenazas, sino confiándose al que juzga con justicia."],["1 Pedro 3:15-17","Los creyentes deben estar preparados para explicar su esperanza con amabilidad y respeto, manteniendo una buena conciencia."]],"a":["Seguir el ejemplo de Cristo significa no buscar nunca protección ni justicia cuando sufrimos abuso; defendernos sería falta de fe.","Seguir haciendo el bien, confiar en la justicia de Dios y responder con una conducta que honre a Cristo.","Todo sufrimiento del creyente es enviado directamente por Dios, por lo que intentar cambiar una situación injusta significa resistir su propósito."],"correct":1,"ex":"Pedro no dice que todo sufrimiento sea justo ni que debamos buscarlo. Enseña cómo responder cuando sufrimos precisamente por hacer el bien: sin abandonar la fidelidad ni convertirnos en aquello que nos hiere."},
{"section":"2 Pedro · Crecimiento","q":"¿Cómo describe Pedro el crecimiento cristiano?","refs":[["2 Pedro 1:3-8","Dios ha dado lo necesario para una vida que le agrada. Pedro llama a añadir a la fe virtud, conocimiento, dominio propio, perseverancia, devoción, afecto fraternal y amor."]],"a":["Como un crecimiento en el que la gracia de Dios produce una vida cada vez más madura y fructífera.","El crecimiento cristiano consiste en adquirir suficiente conocimiento y disciplina hasta llegar a un punto en que dejamos de luchar con el pecado.","Las virtudes cristianas completan lo que le falta a la fe para salvarnos; sin alcanzar suficientes virtudes Dios finalmente nos rechazará."],"correct":0,"ex":"El conocimiento cristiano debe alcanzar la vida. Pedro conecta la fe con carácter, dominio propio, perseverancia y amor."},
{"section":"Evangelios · Gracia","q":"¿Qué quiso enseñar Jesús con la parábola de los trabajadores que recibieron el mismo pago?","refs":[["Mateo 20:1-16","Jesús contó que un dueño contrató trabajadores a diferentes horas del día y al final dio a todos lo que había decidido dar. Algunos se quejaron porque esperaban recibir más que los demás."]],"a":["Que Dios recompensa exactamente según la cantidad de años que una persona le haya servido.","Que la generosidad de Dios no funciona como un salario que podamos exigir por nuestros méritos.","Que todos recibirán exactamente las mismas responsabilidades y recompensas sin importar cómo hayan vivido."],"correct":1,"ex":"La parábola confronta la idea de convertir la gracia en salario. Dios es generoso y nadie puede presentarse ante Él como si su favor fuera una deuda que Él tuviera que pagar."},
{"section":"Evangelios · Fe","q":"¿Qué aprendemos del padre que dijo: “Creo; ayuda mi incredulidad”?","refs":[["Marcos 9:20-24","El padre pidió ayuda a Jesús para su hijo. Cuando Jesús habló de creer, el hombre respondió con sinceridad: creía, pero reconocía que su fe necesitaba ayuda."]],"a":["Que una fe verdadera nunca puede coexistir con preguntas o debilidad.","Que podemos acudir a Jesús con una fe real aunque todavía luchemos con dudas y necesitemos su ayuda.","Que la duda fortalece la fe por sí misma y por eso no necesitamos buscar respuestas."],"correct":1,"ex":"La fe no necesita fingir una seguridad que no posee. Este hombre llevó incluso su debilidad a Jesús. La respuesta no fue abandonar la fe, sino pedir ayuda en medio de ella."},
{"section":"Evangelios · Tradición","q":"¿Qué problema señaló Jesús cuando una tradición religiosa ocupa el lugar de la Palabra de Dios?","refs":[["Marcos 7:6-13","Jesús reprendió a quienes honraban a Dios con los labios mientras elevaban tradiciones humanas de tal manera que terminaban anulando el mandato de Dios."]],"a":["Que toda tradición religiosa es necesariamente contraria a Dios.","Que una tradición puede ser útil, pero nunca debe tener autoridad para corregir, reemplazar o anular lo que Dios ha dicho.","Que las tradiciones antiguas tienen autoridad mientras hayan sido practicadas durante suficiente tiempo."],"correct":1,"ex":"Jesús no condenó algo simplemente por ser tradicional. El problema aparece cuando una costumbre humana recibe una autoridad que pertenece a la Palabra de Dios."},
{"section":"Evangelios · Corazón","q":"Según Jesús, ¿de dónde procede realmente la contaminación moral del ser humano?","refs":[["Marcos 7:20-23","Jesús enseñó que del interior, del corazón humano, salen malos pensamientos, inmoralidad, engaño, orgullo y otros males."]],"a":["Principalmente del ambiente y de las malas influencias que rodean a la persona.","Del corazón humano; por eso necesitamos algo más profundo que cambios externos.","De no conocer suficientes reglas para distinguir correctamente el bien del mal."],"correct":1,"ex":"Jesús lleva el problema hasta el corazón. El entorno influye y la enseñanza importa, pero nuestra necesidad es más profunda que corregir circunstancias externas."},
{"section":"Evangelios · Misericordia","q":"¿Qué quiso decir Jesús con “misericordia quiero y no sacrificio”?","refs":[["Mateo 9:10-13","Cuando criticaron a Jesús por comer con pecadores, Él recordó que los enfermos necesitan médico y citó: misericordia quiero y no sacrificio. Dijo que vino a llamar a pecadores."]],"a":["Que las prácticas religiosas no tienen ningún valor y pueden abandonarse.","Que cumplir actos religiosos mientras despreciamos al necesitado puede revelar que no hemos entendido el corazón de Dios.","Que mostrar misericordia a otros compensa delante de Dios los pecados que hayamos cometido."],"correct":1,"ex":"Jesús confronta una religión exterior capaz de cumplir ceremonias mientras pierde de vista la misericordia. La misericordia no compra el perdón, pero revela comprensión del carácter de Dios."},
{"section":"Evangelios · Fruto","q":"¿Qué quiso decir Jesús al enseñar que el árbol se conoce por su fruto?","refs":[["Mateo 7:15-20","Jesús advirtió sobre falsos profetas y dijo que serían reconocidos por sus frutos, de la misma manera que un árbol se reconoce por lo que produce."]],"a":["Que una persona puede saber con certeza el destino eterno de otra observando algunos errores.","Que con el tiempo, la vida y la enseñanza revelan lo que realmente está produciendo una persona.","Que un verdadero creyente siempre mostrará una conducta perfecta y sin contradicciones."],"correct":1,"ex":"Jesús no nos invita a juzgar precipitadamente por una falla aislada. Habla de fruto: aquello que una vida y una enseñanza producen de manera reconocible."},
{"section":"Evangelios · Tesoro","q":"¿Qué significa acumular tesoros en el cielo?","refs":[["Mateo 6:19-21","Jesús contrastó los tesoros de la tierra, que pueden perderse, con los tesoros del cielo. Añadió que donde esté nuestro tesoro estará también nuestro corazón."]],"a":["Renunciar a toda posesión material, porque tener bienes en la tierra impide servir a Dios.","Vivir dando valor a lo que pertenece al reino de Dios en vez de hacer de lo temporal nuestra seguridad y propósito principal.","Hacer suficientes obras buenas para acumular méritos que Dios utilizará para decidir nuestra entrada al cielo."],"correct":1,"ex":"Jesús apunta al corazón y a aquello que consideramos verdaderamente valioso. No enseña a comprar el cielo con obras, sino a vivir con prioridades que no terminan con lo temporal."},
{"section":"Evangelios · Ansiedad","q":"Cuando Jesús dice “no se preocupen”, ¿enseña que nunca debemos planificar?","refs":[["Mateo 6:25-34","Jesús habló de la preocupación por comida, bebida y vestido. Recordó el cuidado del Padre y llamó a buscar primero el reino de Dios, enfrentando cada día sin cargar anticipadamente con el siguiente."]],"a":["Sí. Planificar el futuro demuestra que todavía no confiamos plenamente en Dios.","No. Jesús confronta la ansiedad que nos domina; podemos actuar responsablemente mientras dependemos del cuidado del Padre.","Solo debemos planificar asuntos espirituales, porque las necesidades materiales deben dejarse completamente en manos de Dios."],"correct":1,"ex":"Jesús no condena la responsabilidad. Enseña a no vivir gobernados por una preocupación que intenta cargar hoy con todos los problemas de mañana."},
{"section":"Evangelios · Juicio","q":"¿Qué significa “no juzguen” en Mateo 7?","refs":[["Mateo 7:1-5","Jesús advirtió contra juzgar hipócritamente: ver una pequeña falta en otro mientras ignoramos una mucho mayor en nosotros. Primero debemos examinarnos y luego podremos ayudar al hermano."],["Mateo 7:15-20","Poco después Jesús manda discernir a los falsos profetas por sus frutos."]],"a":["Que nunca podemos decir que una conducta o enseñanza está equivocada.","Que debemos evitar el juicio hipócrita y examinarnos primero, sin abandonar el discernimiento necesario.","Que solamente quienes no tienen ningún pecado pueden corregir a otra persona."],"correct":1,"ex":"El mismo discurso que dice 'no juzguen' también manda discernir. Jesús condena la hipocresía y la medida orgullosa, no toda evaluación moral o doctrinal."},
{"section":"Evangelios · Mandamientos","q":"¿Qué significa amar a Dios con todo el corazón y al prójimo como a nosotros mismos?","refs":[["Mateo 22:35-40","Jesús dijo que el mandamiento principal es amar a Dios con todo nuestro ser y que el segundo es amar al prójimo como a uno mismo. De estos dependen la Ley y los Profetas."]],"a":["Que si sentimos amor sincero, los demás mandamientos dejan de tener importancia.","Que la obediencia a Dios encuentra su orientación correcta en el amor a Dios y en buscar el bien del prójimo.","Que amar al prójimo es suficiente aunque nuestra relación con Dios no tenga importancia."],"correct":1,"ex":"Jesús no enfrenta amor contra obediencia. Muestra el corazón hacia el cual apunta la voluntad de Dios: amor verdadero hacia Dios y hacia el prójimo."},
{"section":"Evangelios · Cena del Señor","q":"¿Qué anuncia la Cena del Señor acerca de Jesús?","refs":[["Lucas 22:19-20","Jesús tomó pan y vino y los relacionó con su cuerpo entregado y con el nuevo pacto establecido por medio de su sangre."]],"a":["Principalmente la unión y amistad que existe entre quienes comparten una comida cristiana.","La entrega de Jesús por nosotros y el nuevo pacto establecido mediante su muerte.","Que participar del pan y de la copa produce automáticamente perdón, aunque no exista fe."],"correct":1,"ex":"La Cena dirige la mirada hacia Cristo entregado por nosotros. No es solamente compañerismo ni un acto automático separado de la fe."},
{"section":"Evangelios · Espíritu","q":"¿Qué hace el Espíritu Santo según las palabras de Jesús en Juan?","refs":[["Juan 16:7-14","Jesús dijo que el Espíritu convencería al mundo y guiaría a sus discípulos a la verdad, glorificando a Cristo y comunicando lo que recibe de Él."]],"a":["Dirige la atención principalmente hacia las experiencias espirituales de la persona que lo recibe.","Obra para mostrar la verdad acerca del pecado y de Cristo, guiando a los discípulos y glorificando a Jesús.","Trae enseñanzas nuevas que pueden reemplazar las palabras de Jesús cuando la iglesia necesita adaptarse."],"correct":1,"ex":"En Juan, la obra del Espíritu es profundamente cristocéntrica. No compite con Jesús ni desplaza su palabra: glorifica a Cristo y conduce a la verdad."},
{"section":"Evangelios · Permanecer","q":"¿Qué significa permanecer en Cristo, según Juan 15?","refs":[["Juan 15:4-5","Jesús se comparó con la vid y a sus discípulos con las ramas. La rama no puede producir fruto separada de la vid; separados de Él no pueden producir el fruto que Dios busca."]],"a":["Mantener una disciplina espiritual constante para conservar la vida que inicialmente recibimos de Cristo.","Vivir dependiendo continuamente de Cristo, porque el fruto de la vida cristiana nace de nuestra unión con Él.","Conservar una emoción fuerte hacia Jesús para evitar períodos de sequedad espiritual."],"correct":1,"ex":"Permanecer describe dependencia, comunión y continuidad en Cristo. El fruto no nace de independencia religiosa, sino de una vida que recibe de Él."},
{"section":"Evangelios · Servicio","q":"¿Qué enseña Jesús al lavar los pies de sus discípulos?","refs":[["Juan 13:12-17","Después de lavarles los pies, Jesús explicó que siendo Maestro y Señor había servido de esa manera y dejó un ejemplo para que ellos también se sirvieran."]],"a":["Que el lavado de pies es la obra principal mediante la cual demostramos humildad delante de Dios.","Que ninguna posición dentro del pueblo de Dios nos coloca por encima del servicio humilde a otros.","Que un líder cristiano nunca debe ejercer autoridad ni tomar decisiones difíciles."],"correct":1,"ex":"Jesús no elimina el liderazgo, pero destruye la idea de que liderazgo significa superioridad personal. El Señor mismo tomó el lugar del servidor."},
{"section":"Evangelios · Vida eterna","q":"¿Qué es la vida eterna según la oración de Jesús en Juan 17?","refs":[["Juan 17:1-3","Jesús habló de la vida eterna como conocer al único Dios verdadero y a Jesucristo, a quien Él envió."]],"a":["Vivir para siempre, independientemente de la relación que tengamos con Dios.","Conocer al Padre por medio de Jesucristo; es una vida relacionada con Dios que comienza ahora y continúa para siempre.","Alcanzar suficiente conocimiento acerca de Dios para estar preparados para la vida futura."],"correct":1,"ex":"La vida eterna incluye duración, pero Jesús la describe relacionalmente: conocer al Padre y al Hijo. No es simplemente existencia interminable."},
{"section":"Hechos · Berea","q":"¿Por qué fueron elogiados los creyentes de Berea?","refs":[["Hechos 17:10-12","Recibieron el mensaje con disposición y examinaban cada día las Escrituras para comprobar si lo que escuchaban era así."]],"a":["Porque aceptaron inmediatamente la enseñanza de los apóstoles sin cuestionarla.","Porque escucharon con disposición y al mismo tiempo comprobaron la enseñanza a la luz de las Escrituras.","Porque desconfiaban de todo maestro y solo aceptaban lo que podían descubrir sin ayuda."],"correct":1,"ex":"Una actitud enseñable no exige credulidad. Los bereanos escuchaban seriamente y verificaban. Es un buen modelo de humildad y discernimiento."},
{"section":"Hechos · Simón","q":"¿Qué error cometió Simón al querer obtener el poder de Dios con dinero?","refs":[["Hechos 8:18-23","Simón ofreció dinero a los apóstoles para recibir autoridad espiritual. Pedro lo reprendió porque pensó que el don de Dios podía comprarse."]],"a":["Pensó que los dones de Dios podían convertirse en algo que se obtiene y controla para beneficio personal.","Pensó que debía apoyar económicamente el ministerio antes de poder recibir una responsabilidad espiritual.","Quiso recibir un don antes de haber demostrado durante suficiente tiempo que estaba preparado para usarlo."],"correct":0,"ex":"El problema no fue simplemente el dinero. Simón trató el don de Dios como poder adquirible y utilizable. La gracia y el Espíritu no son mercancía."},
{"section":"Hechos · Cornelio","q":"¿Qué aprendió Pedro en la casa de Cornelio?","refs":[["Hechos 10:28-35","Pedro reconoció que Dios le había mostrado que no debía llamar impura a ninguna persona y que Dios no muestra favoritismo entre pueblos."],["Hechos 10:43-48","Pedro anunció perdón por medio de Jesús y el Espíritu Santo vino sobre quienes escuchaban."]],"a":["Que una persona sincera puede ser salva sin Cristo si practica suficientes buenas obras.","Que Dios no limita el Evangelio a una etnia; personas de todas las naciones son llamadas a recibir a Cristo.","Que las diferencias culturales dejan de existir cuando alguien se hace cristiano."],"correct":1,"ex":"El episodio rompe una barrera étnica, no elimina a Cristo. Pedro precisamente anuncia a Jesús y el perdón por medio de su nombre."},
{"section":"Hechos · Discernimiento","q":"¿Qué muestra el concilio de Jerusalén sobre resolver una controversia doctrinal?","refs":[["Hechos 15:5-21","Los apóstoles y ancianos se reunieron para considerar la discusión sobre exigir la circuncisión a los gentiles. Escucharon testimonios, recordaron la obra de Dios y examinaron las Escrituras antes de llegar a una conclusión."]],"a":["Que toda controversia debe resolverse simplemente por votación de la mayoría.","Que la iglesia debe escuchar, considerar la obra de Dios y someter sus conclusiones al testimonio de la Escritura.","Que los líderes con mayor autoridad pueden decidir doctrina sin explicar bíblicamente sus razones."],"correct":1,"ex":"Hechos muestra deliberación comunitaria y atención a la evidencia, pero la decisión no descansa simplemente en preferencias. La Escritura y la obra de Dios son centrales."},
{"section":"Romanos · Obediencia","q":"Si no somos justificados por obras, ¿por qué importa obedecer a Dios?","refs":[["Romanos 6:15-18","Pablo rechaza la idea de pecar porque estamos bajo gracia. Quienes fueron liberados del pecado pasaron a una nueva obediencia de corazón."],["Romanos 12:1-2","A la luz de las misericordias de Dios, Pablo llama a ofrecer la vida a Dios y a ser transformados mediante la renovación de la mente."]],"a":["Porque la obediencia conserva la justificación que inicialmente recibimos por fe.","Porque la obediencia es respuesta y fruto de la misericordia recibida, no el precio con el que compramos nuestra aceptación.","Porque las obras finalmente se suman a la fe para completar la justificación."],"correct":1,"ex":"Romanos no enfrenta gracia contra obediencia. La gracia cambia la raíz de la obediencia: ya no intentamos comprar aceptación, sino responder a la misericordia de Dios."},
{"section":"Romanos · Conciencia","q":"¿Qué enseña Romanos 14 cuando creyentes sinceros llegan a conclusiones diferentes en asuntos discutibles?","refs":[["Romanos 14:1-6","Pablo habla de creyentes que diferían sobre alimentos y días. Ordena recibir al hermano sin discutir para condenarlo, pues cada uno busca honrar al Señor."],["Romanos 14:13-19","Pablo llama a no poner tropiezo al hermano y a buscar lo que produce paz y edificación mutua."]],"a":["Que toda diferencia doctrinal debe tratarse como un asunto sin importancia.","Que en asuntos que no contradicen el Evangelio debemos evitar despreciarnos y actuar con conciencia, amor y consideración mutua.","Que siempre debe ceder quien tiene una conciencia más libre, porque su posición es menos espiritual."],"correct":1,"ex":"Pablo no declara que toda doctrina sea secundaria. Trata asuntos concretos en los que creyentes podían honrar al Señor de manera diferente y llama a la convivencia en amor."},
{"section":"Romanos · Transformación","q":"¿Qué significa ser transformados por la renovación de nuestra mente?","refs":[["Romanos 12:1-2","Pablo llama a no amoldarse a este mundo, sino a ser transformados mediante la renovación de la mente para discernir la voluntad de Dios."]],"a":["Aprender suficientes enseñanzas bíblicas hasta que ya no necesitemos luchar con viejos patrones.","Permitir que la verdad de Dios cambie nuestra manera de pensar y, con ella, nuestra manera de vivir y discernir.","Rechazar todo pensamiento o costumbre que provenga de personas que no sean cristianas."],"correct":1,"ex":"La renovación de la mente no es acumular información ni rechazar automáticamente todo lo cultural. Es una transformación de nuestra manera de pensar bajo la verdad de Dios."},
{"section":"1 Corintios · Libertad","q":"¿Cómo debe usar un cristiano su libertad cuando una decisión puede dañar espiritualmente a otro?","refs":[["1 Corintios 8:9-13","Pablo advierte que la libertad de uno no debe convertirse en tropiezo para el débil. Está dispuesto a renunciar a algo permitido antes que herir la conciencia del hermano."],["1 Corintios 10:23-24","No todo lo permitido conviene o edifica; nadie debe buscar solamente su propio bien, sino también el del otro."]],"a":["Si algo está permitido, debemos hacerlo para enseñar a otros a tener una conciencia más fuerte.","La libertad cristiana está gobernada por el amor; a veces podemos renunciar voluntariamente a un derecho por el bien de otro.","Debemos someternos siempre a la conciencia más estricta de cualquier persona para evitar todo desacuerdo."],"correct":1,"ex":"La libertad no es egoísmo con vocabulario cristiano. Pero tampoco significa quedar gobernados permanentemente por la regla más estricta. Pablo pide amor y edificación."},
{"section":"1 Corintios · Disciplina","q":"¿Para qué sirve la disciplina dentro de la iglesia?","refs":[["1 Corintios 5:1-7","Pablo confronta un pecado grave que la comunidad estaba tolerando y pide actuar en lugar de sentirse orgullosos de su tolerancia."],["2 Corintios 2:6-8","En otro contexto de disciplina, Pablo pide que, después de la corrección suficiente, se perdone, consuele y reafirme el amor."]],"a":["Para proteger la santidad de la comunidad y buscar restauración, no para disfrutar del castigo o exhibir superioridad.","Para mostrar públicamente qué personas han perdido su salvación y separarlas definitivamente.","Para mantener la reputación de la iglesia evitando que los problemas internos sean conocidos."],"correct":0,"ex":"La disciplina bíblica toma el pecado en serio, pero su espíritu no es venganza. La corrección y la restauración deben caminar juntas."},
{"section":"2 Corintios · Debilidad","q":"¿Qué aprendió Pablo cuando pidió que le fuera quitado su “aguijón”?","refs":[["2 Corintios 12:7-10","Pablo pidió tres veces que aquello se apartara. La respuesta del Señor fue que su gracia era suficiente y que su poder se perfeccionaba en la debilidad."]],"a":["Que si oramos suficientes veces, Dios finalmente eliminará aquello que nos hace sufrir.","Que la gracia de Cristo puede sostenernos incluso cuando Dios no elimina una debilidad o dificultad que hemos pedido que quite.","Que debemos dejar de pedir a Dios que cambie circunstancias difíciles porque hacerlo muestra poca fe."],"correct":1,"ex":"Pablo sí pidió que la dificultad fuera quitada. Lo que aprendió fue que una respuesta distinta a la esperada no significa ausencia de gracia."},
{"section":"2 Corintios · Generosidad","q":"¿Cómo describe Pablo la manera cristiana de dar?","refs":[["2 Corintios 9:6-8","Pablo llama a dar según lo decidido en el corazón, no con tristeza ni por obligación, porque Dios ama al que da con alegría."]],"a":["Dar una cantidad suficientemente grande para demostrar nuestra confianza y recibir una bendición proporcional.","Dar voluntariamente y con generosidad, no bajo manipulación o presión, confiando en Dios.","Dar siempre el mismo porcentaje, porque cualquier cantidad menor convierte la ofrenda en desobediencia."],"correct":1,"ex":"Pablo habla de generosidad, pero también de decisión del corazón y ausencia de coacción. Dar no es comprar una devolución de Dios."},
{"section":"Gálatas · Libertad","q":"¿Qué significa la libertad cristiana en Gálatas?","refs":[["Gálatas 5:13-14","Pablo dice que fueron llamados a libertad, pero no para usarla como oportunidad para la carne; mediante el amor deben servirse unos a otros."]],"a":["Que ya no existen mandatos morales para quien vive bajo la gracia.","Que hemos sido liberados de la esclavitud para vivir por el Espíritu y servir en amor, no para vivir dominados por nuestros deseos.","Que somos libres mientras mantengamos mediante nuestra obediencia el derecho a seguir bajo la gracia."],"correct":1,"ex":"La libertad de Gálatas no es autonomía para hacer cualquier cosa. Es libertad de la esclavitud y de la justificación por ley para una vida guiada por el Espíritu."},
{"section":"Gálatas · Restauración","q":"¿Cómo debe tratarse a un creyente sorprendido en una falta?","refs":[["Gálatas 6:1-2","Los espirituales deben restaurar con espíritu de mansedumbre a quien ha caído, cuidándose también a sí mismos y llevando las cargas unos de otros."]],"a":["Debe ser corregido con firmeza pública para que los demás comprendan la gravedad del pecado.","Debe ser restaurado con mansedumbre, sin ignorar la falta y sin olvidar nuestra propia vulnerabilidad.","Es mejor no intervenir, porque cualquier corrección sería juzgar la vida de otra persona."],"correct":1,"ex":"Pablo evita dos extremos: indiferencia y superioridad. La meta es restaurar, y quien ayuda debe recordar que también puede ser tentado."},
{"section":"Efesios · Perdón","q":"¿Cuál es la base para perdonarnos unos a otros?","refs":[["Efesios 4:31-32","Pablo llama a dejar amargura, ira y malicia, y a ser bondadosos y compasivos, perdonándonos como Dios nos perdonó en Cristo."]],"a":["Perdonamos para que Dios vea nuestra misericordia y entonces decida perdonarnos a nosotros.","El perdón que hemos recibido en Cristo se convierte en la base y modelo para perdonar a otros.","Perdonar significa restaurar inmediatamente la misma confianza que existía antes de la ofensa."],"correct":1,"ex":"El perdón cristiano fluye del perdón recibido. Eso no significa que la confianza dañada siempre se reconstruya instantáneamente ni que desaparezcan todas las consecuencias."},
{"section":"Efesios · Guerra espiritual","q":"¿Qué significa ponerse la armadura de Dios?","refs":[["Efesios 6:10-18","Pablo describe verdad, justicia, Evangelio de paz, fe, salvación, palabra de Dios y oración como la armadura con la que los creyentes permanecen firmes."]],"a":["Aprender técnicas especiales para identificar qué espíritu está detrás de cada problema cotidiano.","Permanecer firmes en la verdad, la justicia, el Evangelio, la fe, la salvación, la Palabra y la oración frente al mal.","Mantener una vida sin pecado para impedir que cualquier fuerza espiritual pueda acercarse a nosotros."],"correct":1,"ex":"La imagen de la armadura no dirige a prácticas secretas, sino a realidades centrales de la vida cristiana: verdad, Evangelio, fe, Palabra y oración."},
{"section":"Filipenses · Ansiedad","q":"¿Qué propone Pablo frente a la ansiedad en Filipenses 4?","refs":[["Filipenses 4:6-9","Pablo llama a presentar las peticiones a Dios con oración y gratitud. También anima a orientar la mente hacia lo verdadero, justo, puro y digno."]],"a":["Ignorar los pensamientos preocupantes y repetir que todo saldrá bien hasta sentir paz.","Llevar nuestras preocupaciones a Dios en oración y aprender a orientar la mente hacia lo verdadero y bueno.","Considerar la ansiedad como evidencia de que nuestra fe no es auténtica."],"correct":1,"ex":"Pablo no avergüenza al creyente por experimentar preocupación. Lo dirige hacia Dios, la oración, la gratitud y una mente formada por la verdad."},
{"section":"Colosenses · Reglas","q":"¿Por qué Pablo advierte contra reglas religiosas que parecen muy espirituales pero no transforman el corazón?","refs":[["Colosenses 2:20-23","Pablo menciona mandatos como 'no tomes, no pruebes, no toques'. Dice que tienen apariencia de sabiduría y severidad, pero no tienen poder real contra los deseos de la carne."]],"a":["Porque cualquier regla práctica dentro de la vida cristiana es legalismo.","Porque la disciplina externa puede tener apariencia de santidad sin resolver por sí misma el problema interior del pecado.","Porque una vez que creemos, controlar nuestros deseos deja de ser importante."],"correct":1,"ex":"Pablo no condena toda disciplina. Advierte contra convertir reglas humanas y severidad externa en el poder que supuestamente transforma el corazón."},
{"section":"1 Tesalonicenses · Discernimiento","q":"¿Qué significa “examínenlo todo; retengan lo bueno”?","refs":[["1 Tesalonicenses 5:19-22","Pablo dice que no apaguen al Espíritu ni desprecien las profecías, pero también manda examinarlo todo, retener lo bueno y apartarse del mal."]],"a":["Aceptar primero toda experiencia espiritual y cuestionarla solo si produce algún daño visible.","No rechazar automáticamente lo espiritual, pero tampoco aceptarlo sin discernimiento; debemos examinar y retener lo bueno.","Desconfiar de toda manifestación espiritual porque la única manera segura de evitar el error es rechazarla."],"correct":1,"ex":"Pablo une apertura y discernimiento. Ni credulidad ni rechazo automático: aquello que se presenta como espiritual debe ser examinado."},
{"section":"2 Tesalonicenses · Trabajo","q":"¿Qué problema corrige Pablo cuando dice que quien no quiere trabajar tampoco coma?","refs":[["2 Tesalonicenses 3:10-12","Pablo se refiere a personas que, pudiendo hacerlo, no querían trabajar y vivían desordenadamente ocupándose de asuntos ajenos. Les manda trabajar tranquilamente para obtener su propio alimento."]],"a":["Enseña que toda persona sin empleo debe quedar sin ayuda hasta que consiga trabajo.","Corrige a quienes deliberadamente se niegan a trabajar pudiendo hacerlo; no condena a quien no puede trabajar o necesita ayuda.","Enseña que recibir ayuda de otros creyentes siempre crea dependencia y debe evitarse."],"correct":1,"ex":"El texto dice 'no quiere', no 'no puede'. No debe utilizarse para condenar al enfermo, al vulnerable o a quien atraviesa necesidad real."},
{"section":"1 Timoteo · Liderazgo","q":"¿Qué clase de carácter busca el Nuevo Testamento en un líder de iglesia?","refs":[["1 Timoteo 3:1-7","Pablo destaca sobriedad, dominio propio, hospitalidad, capacidad para enseñar, buen trato de la familia, ausencia de violencia y buena reputación."],["1 Pedro 5:2-3","Pedro pide cuidar al rebaño voluntariamente, sin codicia y sin dominar a quienes están bajo cuidado, sino siendo ejemplo."]],"a":["Principalmente capacidad para hablar, atraer personas y hacer crecer rápidamente la congregación.","Carácter probado, capacidad para enseñar y una manera de liderar que sirva de ejemplo sin dominar al rebaño.","Una autoridad fuerte que haga que los miembros obedezcan incluso cuando no comprenden las decisiones."],"correct":1,"ex":"El Nuevo Testamento dedica sorprendentemente mucho espacio al carácter. El talento no reemplaza integridad, servicio y ejemplo."},
{"section":"2 Timoteo · Enseñanza","q":"¿Cómo debe corregir un siervo del Señor a quien se opone?","refs":[["2 Timoteo 2:23-26","Pablo dice que el siervo del Señor no debe ser pendenciero, sino amable, capaz de enseñar, paciente y dispuesto a corregir con mansedumbre, esperando que Dios conceda arrepentimiento."]],"a":["Debe responder con mayor dureza para evitar que el error parezca aceptable.","Debe enseñar con claridad y mansedumbre, recordando que el cambio del corazón depende de la obra de Dios.","Debe evitar corregir doctrinas falsas porque toda discusión produce división."],"correct":1,"ex":"La mansedumbre no exige debilidad doctrinal. Pablo combina corrección real con paciencia y dependencia de Dios para producir arrepentimiento."},
{"section":"Tito · Gracia","q":"Según Tito 2, ¿qué hace la gracia además de ofrecernos salvación?","refs":[["Tito 2:11-14","La gracia de Dios se manifestó trayendo salvación y enseñándonos a renunciar a la impiedad y vivir de manera sensata, justa y dedicada a Dios mientras esperamos a Cristo."]],"a":["Nos perdona cuando fallamos, pero el cambio de conducta depende de nuestro esfuerzo para conservar ese perdón.","También nos educa: la gracia que salva forma una vida nueva mientras esperamos a Cristo.","Hace innecesaria cualquier enseñanza moral, porque vivir bajo gracia significa actuar únicamente según la conciencia."],"correct":1,"ex":"La gracia no es solamente borrador del pasado. Pablo dice que también nos enseña. Salvación y transformación no son enemigas."},
{"section":"Filemón · Hermandad","q":"¿Qué cambia el Evangelio en la relación entre Filemón y Onésimo?","refs":[["Filemón 15-17","Pablo pide que Onésimo sea recibido ya no simplemente como esclavo, sino como algo mucho mayor: un hermano amado. Le pide a Filemón recibirlo como recibiría al propio Pablo."]],"a":["El Evangelio solo cambia la relación espiritual; las relaciones humanas no necesitan verse afectadas.","La nueva identidad en Cristo transforma la manera de ver y recibir a otra persona, incluso dentro de relaciones sociales profundamente desiguales.","La conversión elimina automáticamente en ese momento todas las estructuras sociales existentes."],"correct":1,"ex":"Pablo lleva la identidad de hermano directamente a una relación concreta. El Evangelio no queda encerrado en lo interior; cambia cómo vemos y tratamos a las personas."},
{"section":"Hebreos · Nuevo pacto","q":"¿Qué significa que Jesús es mediador de un nuevo pacto?","refs":[["Hebreos 8:6-12","Hebreos presenta a Jesús como mediador de un pacto mejor y recuerda la promesa de Dios de escribir su ley en el corazón, ser Dios de su pueblo y perdonar sus pecados."],["Hebreos 9:15","Cristo es mediador de un nuevo pacto para que los llamados reciban la herencia prometida."]],"a":["Que Jesús añadió enseñanzas nuevas al pacto anterior para que podamos cumplirlo mejor.","Que por medio de Cristo Dios establece la relación prometida, trae perdón y obra interiormente en su pueblo.","Que el nuevo pacto significa que Dios ya no espera ninguna obediencia de su pueblo."],"correct":1,"ex":"El nuevo pacto no es simplemente una lista mejor de reglas. Incluye perdón, relación con Dios y una obra interior que transforma a su pueblo."},
{"section":"Hebreos · Reunirse","q":"¿Por qué Hebreos anima a los creyentes a no dejar de reunirse?","refs":[["Hebreos 10:23-25","Se llama a mantener firme la esperanza, pensar cómo estimularnos al amor y a las buenas obras, no abandonar la reunión y animarnos mutuamente."]],"a":["Porque faltar a una reunión pone automáticamente en peligro nuestra salvación.","Porque necesitamos animarnos, estimularnos al amor y perseverar juntos en la esperanza.","Porque la presencia en las reuniones es la principal evidencia de que una persona es cristiana."],"correct":1,"ex":"El texto no presenta asistencia como una ficha para ganar salvación. La comunidad importa porque necesitamos mutuamente ánimo, amor y perseverancia."},
{"section":"Santiago · Palabra","q":"¿Qué significa ser hacedor de la Palabra y no solamente oidor?","refs":[["Santiago 1:22-25","Santiago compara al que oye pero no practica con alguien que mira su rostro en un espejo y luego olvida cómo era. El que persevera en la palabra y la practica es llamado bienaventurado."]],"a":["Que escuchar enseñanza bíblica tiene poco valor y lo importante son solamente nuestras acciones.","Que recibir la Palabra verdaderamente implica permitir que lo escuchado alcance nuestra manera de vivir.","Que practicar la Palabra es lo que convierte el mensaje de Dios en verdadero para nosotros."],"correct":1,"ex":"Santiago no enfrenta escuchar contra hacer. Confronta escuchar sin responder. La Palabra debe ser recibida de una manera que transforme la práctica."},
{"section":"Santiago · Lengua","q":"¿Por qué Santiago da tanta importancia a nuestras palabras?","refs":[["Santiago 3:2-10","Santiago compara la lengua con un pequeño timón y con fuego: algo pequeño puede dirigir o dañar muchísimo. Con la misma boca podemos bendecir a Dios y herir a personas hechas a su semejanza."]],"a":["Porque las palabras son pecados más graves que las acciones físicas.","Porque nuestras palabras tienen gran poder para dirigir, construir o destruir y revelan contradicciones profundas del corazón.","Porque un creyente maduro nunca debería expresar desacuerdo de manera directa."],"correct":1,"ex":"Santiago no pide silencio permanente ni evita el desacuerdo. Nos obliga a tomar en serio el poder moral de la manera en que hablamos."},
{"section":"1 Pedro · Defensa de la fe","q":"¿Cómo debemos explicar nuestra esperanza a quien nos pregunta?","refs":[["1 Pedro 3:15-16","Pedro llama a estar preparados para responder acerca de la esperanza, pero hacerlo con mansedumbre y respeto, manteniendo buena conciencia."]],"a":["Con argumentos contundentes que dejen sin respuesta a quien se opone.","Con preparación y claridad, pero también con mansedumbre, respeto y una conducta coherente.","Evitando responder preguntas difíciles para no entrar en discusiones que puedan debilitar nuestra fe."],"correct":1,"ex":"La defensa de la fe no es una competencia para humillar al otro. Pedro une contenido, actitud y conducta."},
{"section":"2 Pedro · Escritura","q":"¿Qué advierte Pedro acerca de interpretar las Escrituras?","refs":[["2 Pedro 3:15-18","Pedro reconoce que en las cartas de Pablo hay cosas difíciles de entender y que personas ignorantes e inestables las tuercen, como hacen también con las demás Escrituras, para su propia destrucción."]],"a":["Que cualquier interpretación sincera es válida mientras ayude espiritualmente a la persona.","Que algunos textos son difíciles y pueden ser torcidos; necesitamos humildad, estabilidad y cuidado al interpretarlos.","Que solamente especialistas pueden comprender la Biblia y los demás creyentes no deberían interpretarla."],"correct":1,"ex":"Pedro reconoce dificultad real sin declarar inaccesible la Escritura. La respuesta a textos difíciles es cuidado y crecimiento, no inventar significados ni abandonar su lectura."},
{"section":"1 Juan · Pecado","q":"¿Cómo puede Juan decir que el creyente no debe vivir en pecado y a la vez enseñar que todavía puede pecar?","refs":[["1 Juan 1:8-2:2","Juan dice que afirmar que no tenemos pecado es engañarnos; si pecamos, tenemos abogado ante el Padre: Jesucristo."],["1 Juan 3:6-10","Juan también enseña que quien permanece en Cristo no puede hacer del pecado su práctica normal, porque la vida nacida de Dios produce una dirección diferente."]],"a":["Juan enseña que los creyentes verdaderos dejan completamente de pecar; 1 Juan 1 se refiere solo a personas no convertidas.","Juan distingue entre reconocer que todavía pecamos y vivir haciendo del pecado nuestra práctica e identidad sin arrepentimiento.","Mientras confesemos nuestros pecados, no importa si decidimos continuar practicándolos."],"correct":1,"ex":"Juan rechaza tanto el perfeccionismo como una fe indiferente al pecado. El creyente todavía necesita perdón, pero la vida nacida de Dios cambia su relación con el pecado."},
{"section":"1 Juan · Verdad y amor","q":"¿Puede el amor cristiano separarse de la verdad?","refs":[["1 Juan 3:18","Juan llama a no amar solamente de palabra, sino con hechos y verdad."],["2 Juan 5-6","Juan une amor y obediencia: amar significa caminar según los mandamientos de Dios."]],"a":["Sí. Amar significa aceptar las decisiones de otra persona aunque sepamos que pueden dañarla.","No. El amor bíblico busca el bien real y camina junto con la verdad y la obediencia a Dios.","No. Por eso decir la verdad siempre es amoroso, sin importar la manera o intención con que se diga."],"correct":1,"ex":"El amor sin verdad puede convertirse en indiferencia, y la verdad sin amor puede utilizarse como arma. Juan mantiene ambas unidas."},
{"section":"3 Juan · Hospitalidad","q":"¿Qué enseña 3 Juan sobre apoyar a quienes sirven al Evangelio?","refs":[["3 Juan 5-8","Juan elogia la fidelidad mostrada al recibir y ayudar a hermanos que salieron por causa del nombre de Cristo. Dice que al apoyarlos colaboramos con la verdad."]],"a":["Que todo predicador cristiano debe recibir apoyo económico sin que sea necesario examinar su enseñanza.","Que ayudar fielmente a quienes sirven a Cristo puede convertirnos en colaboradores de la verdad.","Que solo quienes predican públicamente participan realmente en la misión de la iglesia."],"correct":1,"ex":"No todos cumplen la misma función. Juan muestra que recibir y sostener fielmente a quienes sirven también es participar en la obra."},
{"section":"Judas · Gracia","q":"¿Qué error denuncia Judas en quienes convierten la gracia en permiso para pecar?","refs":[["Judas 3-4","Judas advierte sobre personas que se infiltraron y pervirtieron la gracia de Dios convirtiéndola en libertinaje, negando con su vida al único Señor."]],"a":["Pensar que la gracia es suficiente para salvar sin añadir nuestras obras como garantía.","Usar la gracia como excusa para vivir deliberadamente contra el Señor que decimos seguir.","Creer que Dios puede perdonar pecados graves cuando existe arrepentimiento verdadero."],"correct":1,"ex":"Judas no corrige la grandeza de la gracia, sino su distorsión. La gracia no convierte el pecado en algo bueno ni elimina el señorío de Cristo."},
{"section":"Apocalipsis · Iglesias","q":"¿Qué muestra el mensaje de Jesús a las siete iglesias?","refs":[["Apocalipsis 2:1-3:22","Jesús conoce las obras, sufrimientos, fidelidad, pecados y peligros de las iglesias. Elogia lo bueno, confronta lo malo y llama al arrepentimiento y a perseverar."]],"a":["Que una iglesia verdadera siempre recibe aprobación completa de Jesús aunque tenga problemas graves.","Que Cristo conoce realmente a sus iglesias, puede reconocer su fidelidad y también confrontarlas cuando necesitan arrepentirse.","Que los problemas de aquellas iglesias pertenecían solamente al primer siglo y no enseñan nada a las iglesias posteriores."],"correct":1,"ex":"Las cartas muestran a Cristo presente y evaluando a su pueblo. El amor de Cristo no le impide corregir, y la corrección no significa que ignore la fidelidad."},
{"section":"Apocalipsis · Adoración","q":"¿Por qué la adoración pertenece solamente a Dios y al Cordero?","refs":[["Apocalipsis 5:11-14","Toda la creación atribuye al que está sentado en el trono y al Cordero bendición, honor, gloria y poder."],["Apocalipsis 22:8-9","Cuando Juan intenta postrarse ante el ángel, este se lo impide y le dice: adora a Dios."]],"a":["Porque los ángeles tienen menos poder espiritual y por eso reciben una forma menor de veneración.","Porque la adoración pertenece a Dios; incluso los mensajeros celestiales rechazan ocupar ese lugar.","Porque cualquier expresión de respeto hacia una persona o autoridad equivale a adoración."],"correct":1,"ex":"Apocalipsis marca una frontera clara: incluso un ángel poderoso rechaza la adoración. El Cordero, en cambio, participa de la adoración celestial."}];
